const { withAppBuildGradle } = require('@expo/config-plugins');

/**
 * Wires the real upload keystore into the release build type.
 *
 * `android/` is generated by prebuild and gitignored, so editing its
 * build.gradle by hand does not survive the next `expo prebuild`. This plugin
 * re-applies the signing config every time the native project is generated.
 *
 * The credentials themselves live outside the repo, in
 * `~/.gradle/gradle.properties`, alongside a note pointing at the keystore.
 * When those properties are absent (a fresh clone, CI without secrets) the
 * release build falls back to the debug keystore so it still builds, just
 * un-distributably. Check the signer before shipping, never assume.
 */

const SIGNING_CONFIG = `        release {
            if (project.hasProperty('HITECHBIMS_UPLOAD_STORE_FILE')) {
                storeFile file(HITECHBIMS_UPLOAD_STORE_FILE)
                storePassword HITECHBIMS_UPLOAD_STORE_PASSWORD
                keyAlias HITECHBIMS_UPLOAD_KEY_ALIAS
                keyPassword HITECHBIMS_UPLOAD_KEY_PASSWORD
            }
        }
`;

const SIGNING_ANCHOR = '    signingConfigs {\n';

const BUILD_TYPE_ANCHOR =
  '            // see https://reactnative.dev/docs/signed-apk-android.\n' +
  '            signingConfig signingConfigs.debug';

const BUILD_TYPE_REPLACEMENT =
  '            // Signed by ./plugins/withReleaseSigning.js from the upload\n' +
  '            // keystore, falling back to debug when credentials are absent.\n' +
  "            signingConfig project.hasProperty('HITECHBIMS_UPLOAD_STORE_FILE')\n" +
  '                ? signingConfigs.release\n' +
  '                : signingConfigs.debug';

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    let contents = gradleConfig.modResults.contents;

    if (contents.includes('HITECHBIMS_UPLOAD_STORE_FILE')) {
      return gradleConfig;
    }

    // Fail loudly rather than silently producing a debug-signed release if the
    // upstream template ever changes these lines.
    if (!contents.includes(SIGNING_ANCHOR)) {
      throw new Error(
        'withReleaseSigning: could not find the signingConfigs block in app/build.gradle'
      );
    }
    if (!contents.includes(BUILD_TYPE_ANCHOR)) {
      throw new Error(
        'withReleaseSigning: could not find the release buildType signingConfig in app/build.gradle'
      );
    }

    contents = contents.replace(SIGNING_ANCHOR, SIGNING_ANCHOR + SIGNING_CONFIG);
    contents = contents.replace(BUILD_TYPE_ANCHOR, BUILD_TYPE_REPLACEMENT);

    gradleConfig.modResults.contents = contents;
    return gradleConfig;
  });
};
